#!/usr/bin/env node
// mockup-config-check.mjs
// Lists the mockup blueprint questions a project's
// ${aiDir}/conventions/mockup-design.md has never been asked in their current
// form (`update` and `feature-mockup-review` run it), and stamps the file.
//
// The file is generated by `/myspec:setup mockup` and holds the project's
// answers. A release that adds or changes a question adds a row to the
// blueprint's *Question changes* table:
//
//   | Question | Writes | Since |
//   | Q13 | ## Motion (new section) | 3.8.0 |
//
// This script compares each row's version with the file's frontmatter
// `myspec_version` (a file without a readable stamp counts as BASE_VERSION,
// the release that added the blueprint) and prints the newer rows, the
// newest per question and target. It never reads or edits the body of the file.
//
// Usage:
//   node <plugin>/lib/mockup-config-check.mjs [--root <checkout>] [--file <path>] [--blueprint <path>] [--stamp]
//
// --root defaults to the nearest directory at or above the current one that
// holds .myspec.json. --file and --blueprint resolve against it.
// --stamp sets `myspec_version` to the plugin's own version (its
// framework-files/manifest.json), adding the key when absent. It edits an
// existing frontmatter block only (line 1 `---`, a BOM allowed, YAML lines
// only); any other file is refused, never given a block.
//
// Exit: 0 nothing to ask (or stamped), 3 questions to ask, 4 the file does
// not exist, 2 usage error, a blueprint or manifest it cannot read or parse
// (a table row it cannot read is an error, never skipped), a file it cannot
// stamp, or a file it cannot read or write.

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { aiDirFor, scalarField } from './memory-files.mjs';
import { compareVersions, normalizeVersion } from './upgrade-route.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const PLUGIN_ROOT = join(HERE, '..');
export const BASE_VERSION = '1.20.0';
export const TABLE_HEADING = '## Question changes';
const HEADER = ['question', 'writes', 'since'];
const BOM = '﻿';
const ROW_FORM = '| Q<n> | <what it writes> | X.Y.Z |';
// The *Writes* forms the blueprint's procedure knows how to write.
const WRITES = /^(?:## \S.*? \((?:new section|in section|replaces section)\)|\.myspec\.json mockups\.[A-Za-z0-9_.-]+)$/;
// A line a YAML frontmatter block can hold; a block with any other line is a
// pair of horizontal rules, not frontmatter.
const YAML_LINE = /^(?:\s*$|\s*#|[A-Za-z_][\w-]*\s*:|\s+\S|- )/;

// A table row's cells, split on unescaped pipes; `\|` becomes `|`.
export const cells = (line) =>
  line
    .trim()
    .replace(/^\|/, '')
    .replace(/(?<!\\)\|$/, '')
    .split(/(?<!\\)\|/)
    .map((c) => c.trim().replace(/\\\|/g, '|'));

// Rows of the blueprint's *Question changes* table: [{ q, writes, since }].
// The table is everything from the first `|` line to the next heading; blank
// lines may sit between rows, any other line there is an error, as is a row
// it cannot read, so a malformed row never goes unnoticed.
export function questionChanges(blueprint) {
  const lines = blueprint.split('\n').map((l) => l.replace(/\r$/, ''));
  const start = lines.findIndex((l) => l.trim() === TABLE_HEADING);

  if (start < 0) {
    throw new Error(`no "${TABLE_HEADING}" section`);
  }

  const rows = [];
  let header = null;

  for (let i = start + 1; i < lines.length && !/^#{1,3} /.test(lines[i]); i++) {
    const t = lines[i].trim();

    if (header === null) {
      if (t.startsWith('|')) {
        // The first table line must be the header, or the first row would be
        // taken for it and never offered.
        if (cells(t).map((c) => c.toLowerCase()).join('|') !== HEADER.join('|')) {
          throw new Error(`the ${TABLE_HEADING} table must start with its header row | Question | Writes | Since |, found "${t}"`);
        }

        header = i;
      }

      continue;
    }

    if (t === '') {
      continue;
    }

    const row = t.startsWith('|') ? cells(t) : [];

    if (row.length && row.every((c) => /^:?-+:?$/.test(c))) {
      continue;
    }

    const q = /^Q?(\d+)$/i.exec(row[0] ?? '');
    const since = normalizeVersion(row[2] ?? '');

    if (row.length !== 3 || !q || !since || !row[1]) {
      throw new Error(`cannot read the ${TABLE_HEADING} line "${t}" (want ${ROW_FORM}, or move prose below the table under its own heading)`);
    }

    if (!WRITES.test(row[1])) {
      throw new Error(`the ${TABLE_HEADING} row "${t}" names no known Writes form (see ### Writes forms)`);
    }

    rows.push({ q: Number(q[1]), writes: row[1], since });
  }

  if (header === null) {
    throw new Error(`no table under "${TABLE_HEADING}"`);
  }

  return rows;
}

// The frontmatter block: line 1 (after a BOM) is `---`, the block closes at
// the next line that is `---` once trimmed, and every line between could be
// YAML. Returns { bom, lines, close }, close -1 when there is no such block.
export function frontmatter(text) {
  const bom = text.startsWith(BOM) ? BOM : '';
  const lines = text.slice(bom.length).split('\n');
  let close = lines[0].trim() === '---' ? lines.findIndex((l, i) => i > 0 && l.trim() === '---') : -1;

  if (close > 0 && !lines.slice(1, close).every((l) => YAML_LINE.test(l.replace(/\r$/, '')))) {
    close = -1;
  }

  return { bom, lines, close };
}

// The file's stamp as X.Y.Z, or null when absent or not a version.
export function stampOf(text) {
  const { lines, close } = frontmatter(text);

  if (close < 0) {
    return null;
  }

  const raw = scalarField(lines.slice(1, close).map((l) => l.replace(/\r$/, '')).join('\n'), 'myspec_version');

  return raw ? normalizeVersion(raw) || null : null;
}

// What a row writes to, without its form: rows for the same question and
// target are one change, asked in its newest form.
const target = (writes) => writes.replace(/ \([^)]*\)$/, '');

// The rows newer than the stamp: per question and target, the newest row; a
// question whose releases wrote to different targets is asked for each.
export function pending(rows, stamp) {
  const newest = new Map();

  for (const r of rows) {
    const key = `${r.q} ${target(r.writes)}`;
    const kept = newest.get(key);

    if (compareVersions(r.since, stamp ?? BASE_VERSION) > 0 && (!kept || compareVersions(r.since, kept.since) >= 0)) {
      newest.set(key, r);
    }
  }

  return [...newest.values()].sort((a, b) => a.q - b.q || compareVersions(a.since, b.since));
}

// Sets `myspec_version` in the existing frontmatter block. Returns null when
// there is no closed block.
export function withStamp(text, version) {
  const { bom, lines, close } = frontmatter(text);

  if (close < 0) {
    return null;
  }

  const cr = lines[0].endsWith('\r') ? '\r' : '';
  const line = `myspec_version: ${version}${cr}`;
  const at = lines.findIndex((l, i) => i > 0 && i < close && /^myspec_version:/.test(l));

  if (at > 0) {
    lines[at] = line;
  } else {
    lines.splice(close, 0, line);
  }

  return bom + lines.join('\n');
}

export function pluginVersion(root = PLUGIN_ROOT) {
  const manifest = JSON.parse(readFileSync(join(root, 'framework-files', 'manifest.json'), 'utf8'));
  const version = normalizeVersion(manifest.frameworkVersion);

  if (!version) {
    throw new Error(`plugin manifest frameworkVersion "${manifest.frameworkVersion}" is not a version`);
  }

  return version;
}

// The nearest directory at or above `from` holding .myspec.json, else `from`.
export function projectRoot(from) {
  for (let dir = resolve(from); ; dir = dirname(dir)) {
    if (existsSync(join(dir, '.myspec.json'))) {
      return dir;
    }

    if (dirname(dir) === dir) {
      return resolve(from);
    }
  }
}

const USAGE = 'usage: mockup-config-check.mjs [--root <checkout>] [--file <path>] [--blueprint <path>] [--stamp]\n';

function main(argv) {
  const opts = { '--root': null, '--file': null, '--blueprint': null };
  let doStamp = false;

  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--stamp') {
      doStamp = true;
    } else if (Object.hasOwn(opts, argv[i]) && argv[i + 1] !== undefined) {
      opts[argv[i]] = argv[++i];
    } else {
      process.stderr.write(USAGE);

      return 2;
    }
  }

  const root = opts['--root'] ? resolve(opts['--root']) : projectRoot(process.cwd());
  const file = opts['--file'] ? resolve(root, opts['--file']) : resolve(root, aiDirFor(root), 'conventions', 'mockup-design.md');
  const blueprint = opts['--blueprint'] ? resolve(root, opts['--blueprint']) : join(PLUGIN_ROOT, 'blueprints', 'mockup.md');
  const rel = relative(root, file) || file;

  if (!existsSync(file)) {
    process.stdout.write(`mockup-config-check: ${rel} does not exist; /myspec:setup mockup generates it\n`);

    return 4;
  }

  const text = readFileSync(file, 'utf8');

  if (doStamp) {
    const version = pluginVersion();
    const stamped = withStamp(text, version);

    if (stamped === null) {
      process.stderr.write(`mockup-config-check: ${rel} has no closed frontmatter block to stamp; give it one (--- … ---), then stamp\n`);

      return 2;
    }

    writeFileSync(file, stamped);
    process.stdout.write(`stamped: ${rel}  myspec_version: ${version}\n`);

    return 0;
  }

  const rows = questionChanges(readFileSync(blueprint, 'utf8'));
  const stamp = stampOf(text);
  const asks = pending(rows, stamp);
  const out = [`file: ${rel}  myspec_version: ${stamp ?? `unstamped (counted as ${BASE_VERSION})`}`];

  for (const r of asks) {
    out.push(`ask: Q${r.q}  writes: ${r.writes}  (since ${r.since})`);
  }

  out.push(`mockup-config-check: ${asks.length} question(s) to ask`);
  process.stdout.write(`${out.join('\n')}\n`);

  return asks.length ? 3 : 0;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  let status;

  try {
    status = main(process.argv.slice(2));
  } catch (err) {
    // An unreadable blueprint, manifest or file: report it, never a stack trace.
    process.stderr.write(`mockup-config-check: ${err.message}\n`);
    status = 2;
  }

  process.exit(status);
}
